ORDINAL = {"1": "birinci", "2": "ikinci", "3": "üçüncü", "4": "dördüncü"}
SERVICE_ERROR = "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum."
