        else:
            vars["week_fail_line"] = WEEK_FAIL
        vars["route"] = "fail"
    except Exception:
        vars["week_fail_line"] = WEEK_FAIL
        vars["route"] = "fail"


def apply_which(vars):
    try:
        line = "Ekstre kesim tarihinizi değiştirmemi mi istersiniz, yoksa ekstrenizi e-posta ile göndermemi mi?"
        vars["question_line"] = line
        vars["replay_line"] = line
