def _select(vars, card):
    if card.get("main") is False:
        vars["question_line"] = "Bu kart bu adım için uygun değil. Başka bir kartınızı söyler misiniz?"
        vars["replay_line"] = vars["question_line"]
        vars["resume_at"] = "choose_card"
