def _week_ordinal(raw):
    text = str(raw or "").strip()
    if text in ORDINAL:
        return text, ORDINAL[text]
    try:
        n = str(int(float(text)))
    except Exception:
        return "", ""
    if n in ORDINAL:
        return n, ORDINAL[n]
    return "", ""


def _related_name(data):
    name = str(data.get("relatedCardProductName") or "").strip()
