    elif relation == "M" and related:
        who = name if name else "Sonu " + last4 + " ile biten kartınız"
        if name:
            line = (
                "Son dört hanesi " + last4 + " olan " + name + " kartınız ile buna bağlı " + related
                + " kartınızın ödeme günü her ayın " + ordinal + " haftasına alınacak."
            )
        else:
