def apply_full(vars):
    try:
        cards = _pending(vars, _load_cards(vars))
        digits = digits_of(vars.get("full_said"))
        found = _by_full(cards, digits)
        if len(found) == 1:
            if _select(vars, found[0]):
                vars["route"] = "selected"
