def parse_week(text, current):
    t = tr_lower(text)
    for word, number in (("dördüncü", "4"), ("dorduncu", "4"), ("üçüncü", "3"), ("ucuncu", "3"), ("ikinci", "2"), ("birinci", "1")):
        if word in t:
            return number
    digits = digits_of(t)
    if digits in ("1", "2", "3", "4"):
        return digits
    return ""


